SELECT p.gender, a.admittime, percentile_cont(0.25) within GROUP (ORDER BY COUNT(p.icd_code)) AS p25, percentile_cont(0.75) within GROUP (ORDER BY COUNT(p.icd_code)) AS p75 FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 53 AND 63 AND d.icd_code IN ('G41.9', 'G42.9', 'G43.9', 'G44.9', 'G45.9', 'G46.9', 'G47.9', 'G48.9', 'G49.9') AND (a.dischtime - a.admittime) BETWEEN 1 AND 8 GROUP BY p.gender, a.admittime ORDER BY p.gender, a.admittime NULLS LAST;